import Foundation
import Network
@testable import NetworkClient
import Security

/// Throwaway TLS identities generated by `Scripts/mtls/certs.sh` (localhost only, dev
/// CA, never used anywhere else). Not secrets.
enum MutualTLSFixtures {
    static let passphrase = "nextexplorer"

    static func data(_ name: String, _ ext: String) throws -> Data {
        guard let url = Bundle.module.url(forResource: name, withExtension: ext, subdirectory: "Fixtures") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try Data(contentsOf: url)
    }

    static func certificateAuthority() throws -> SecCertificate {
        guard let certificate = try SecCertificateCreateWithData(nil, data("ca", "der") as CFData) else {
            throw CocoaError(.fileReadCorruptFile)
        }
        return certificate
    }

    /// Anchors evaluation to the dev CA alone. The basic X.509 policy skips the TLS server
    /// lifetime cap, so the long lived fixtures keep CI green for years.
    static func evaluate(_ trust: SecTrust, anchor: SecCertificate) -> Bool {
        SecTrustSetPolicies(trust, SecPolicyCreateBasicX509())
        SecTrustSetAnchorCertificates(trust, [anchor] as CFArray)
        SecTrustSetAnchorCertificatesOnly(trust, true)
        return SecTrustEvaluateWithError(trust, nil)
    }
}

struct DevCATrustEvaluator: ServerTrustEvaluating {
    let anchor: SecCertificate

    func evaluate(_ challenge: URLAuthenticationChallenge) async -> (URLSession.AuthChallengeDisposition, URLCredential?) {
        guard
            challenge.protectionSpace.authenticationMethod == NSURLAuthenticationMethodServerTrust,
            let trust = challenge.protectionSpace.serverTrust
        else {
            return (.performDefaultHandling, nil)
        }
        guard MutualTLSFixtures.evaluate(trust, anchor: anchor) else {
            return (.cancelAuthenticationChallenge, nil)
        }
        return (.useCredential, URLCredential(trust: trust))
    }
}

extension SecCertificate: @retroactive @unchecked Sendable {}

/// A minimal HTTPS server on localhost that, like a reverse proxy with client auth on,
/// refuses any handshake without a client certificate issued by the dev CA, and answers
/// every request that gets through with `200 ok`.
final class MutualTLSTestServer: @unchecked Sendable {
    private let listener: NWListener
    private let queue = DispatchQueue(label: "MutualTLSTestServer")

    init() throws {
        let serverIdentity = try PKCS12Identity.decode(
            MutualTLSFixtures.data("server", "p12"), passphrase: MutualTLSFixtures.passphrase
        )
        let anchor = try MutualTLSFixtures.certificateAuthority()
        let tls = NWProtocolTLS.Options()
        let options = tls.securityProtocolOptions
        guard let localIdentity = sec_identity_create(serverIdentity.identity) else {
            throw CocoaError(.fileReadCorruptFile)
        }
        sec_protocol_options_set_local_identity(options, localIdentity)
        sec_protocol_options_set_peer_authentication_required(options, true)
        sec_protocol_options_set_verify_block(options, { _, trust, complete in
            let secTrust = sec_trust_copy_ref(trust).takeRetainedValue()
            complete(MutualTLSFixtures.evaluate(secTrust, anchor: anchor))
        }, queue)
        listener = try NWListener(using: NWParameters(tls: tls), on: .any)
    }

    /// Starts listening and returns the base URL once the port is bound.
    func start() async throws -> URL {
        listener.newConnectionHandler = { [queue] connection in
            connection.start(queue: queue)
            Self.serve(connection)
        }
        let port: UInt16 = try await withCheckedThrowingContinuation { continuation in
            let resumed = LockedFlag()
            listener.stateUpdateHandler = { [listener] state in
                switch state {
                case .ready:
                    if resumed.set() {
                        continuation.resume(returning: listener.port?.rawValue ?? 0)
                    }
                case let .failed(error):
                    if resumed.set() {
                        continuation.resume(throwing: error)
                    }
                default:
                    break
                }
            }
            listener.start(queue: queue)
        }
        return URL(string: "https://localhost:\(port)")!
    }

    func stop() {
        listener.cancel()
    }

    private static func serve(_ connection: NWConnection, buffer: Data = Data()) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 16384) { data, _, isComplete, error in
            var received = buffer
            if let data {
                received.append(data)
            }
            guard error == nil, !isComplete || !received.isEmpty else {
                connection.cancel()
                return
            }
            guard received.range(of: Data("\r\n\r\n".utf8)) != nil else {
                serve(connection, buffer: received)
                return
            }
            let response = "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok"
            connection.send(content: Data(response.utf8), completion: .contentProcessed { _ in
                connection.cancel()
            })
        }
    }
}

private final class LockedFlag: @unchecked Sendable {
    private let lock = NSLock()
    private var isSet = false

    /// Returns `true` only for the first caller.
    func set() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        guard !isSet else { return false }
        isSet = true
        return true
    }
}
